264	// parseGitHubRelease parses the GitHub API response and returns the latest stable version tag.
265	// Filters out prerelease versions.
266	func parseGitHubRelease(body []byte) (string, error) {
267		var release GitHubRelease
268		if err := json.Unmarshal(body, &release); err != nil {
269			return "", fmt.Errorf("parsing JSON: %w", err)
270		}
271	
272		if release.Prerelease {
273			return "", errors.New("only prerelease versions available")
274		}
275	
276		if release.TagName == "" {
277			return "", errors.New("empty tag name")
278		}
279	
280		return release.TagName, nil
281	}
282	
283	// isOutdated compares current and latest versions using semantic versioning.
284	// Returns true if current < latest.
285	func isOutdated(current, latest string) bool {
286		// Ensure versions have "v" prefix for semver package
287		if !strings.HasPrefix(current, "v") {
288			current = "v" + current
289		}
290		if !strings.HasPrefix(latest, "v") {
291			latest = "v" + latest
292		}
293	
294		// Local/unreleased builds shouldn't trigger update notifications.
295		// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
296		if isDevBuild(current) {
297			return false
298		}
299	
300		// semver.Compare returns -1 if current < latest
301		return semver.Compare(current, latest) < 0
302	}
303	
304	// isDevBuild reports whether v identifies a local, unreleased build that
305	// should not be nagged to update. This covers the "dev" sentinel and empty
306	// string (an unstamped binary), a Go pseudo-version (built from a commit that
307	// isn't a tagged release), and any build carrying +metadata such as "+dirty".
308	// Released builds — stable tags, nightly tags, and `go install ...@<tag>` —
309	// have clean semver and return false.
310	func isDevBuild(v string) bool {
311		if v == "" || v == "dev" {
312			return true
313		}
314		if !strings.HasPrefix(v, "v") {
315			v = "v" + v
316		}
317		return !semver.IsValid(v) || module.IsPseudoVersion(v) || semver.Build(v) != ""
318	}
319	
320	func versionCacheKey(version string) string {
321		if version == "" || strings.HasPrefix(version, "v") {
322			return version
323		}
324		return "v" + version
325	}
326	
327	func displayVersion(version string) string {
328		return strings.TrimPrefix(version, "v")
329	}
330	
331	func releaseNotesURL(version string) string {
332		return downloadsURL + "/tag/" + versionCacheKey(version)
333	}
334	
335	// executablePath is the function used to get the current executable path.
336	// It's a variable so tests can override it.
337	var executablePath = os.Executable
338	
339	func releaseChannel(version string) string {
340		if isNightly(version) {
341			return installChannelNightly
342		}
343		return installChannelStable
344	}
345	
346	func installManagerForCurrentBinary() string {
347		execPath, err := executablePath()
348		if err != nil {
349			return installManagerUnknown
350		}
351	
352		realPath, err := filepath.EvalSymlinks(execPath)
353		if err != nil {
354			realPath = execPath
355		}
356		normalizedPath := strings.ReplaceAll(filepath.ToSlash(realPath), "\\", "/")
357	
358		switch {
359		case strings.Contains(normalizedPath, "/Cellar/") ||
360			strings.Contains(normalizedPath, "/opt/homebrew/") ||
361			strings.Contains(normalizedPath, "/linuxbrew/") ||
362			strings.Contains(normalizedPath, "/Caskroom/"):
363			return installManagerBrew
364		case strings.Contains(normalizedPath, "/mise/installs/"):
365			return installManagerMise
366		case strings.Contains(normalizedPath, "/scoop/apps/"):
367			return installManagerScoop
368		default:
369			return installManagerUnknown
370		}
371	}
372	
373	// canAutoInstall reports whether updateCommand(currentVersion) is safe to
374	// execute on the current OS. Returns false on Windows when the install
375	// manager is unknown, because the POSIX curl-pipe-bash fallback can't run
376	// from cmd.exe and there's no Windows-native installer to substitute.
377	func canAutoInstall() bool {
378		if goos != goosWindows {
379			return true
380		}
381		switch installManagerForCurrentBinary() {
382		case installManagerScoop, installManagerMise:
383			return true
384		default:
385			return false
386		}
387	}
388	
389	// downloadsURL is the public page users visit when we can't offer an
390	// auto-installable command on their platform.
391	const downloadsURL = "https://github.com/entireio/cli/releases"
392	
393	// updateCommand returns the appropriate update instruction based on how the binary was installed.
394	func updateCommand(currentVersion string) string {
395		switch installManagerForCurrentBinary() {
396		case installManagerBrew:
397			if releaseChannel(currentVersion) == installChannelNightly {
398				return "brew upgrade --yes entire@nightly"
399			}
400			return "brew upgrade --yes entire"
401		case installManagerMise:
402			return "mise upgrade entire"
403		case installManagerScoop:
404			return "scoop update entire/cli"
405		}
406	
407		if releaseChannel(currentVersion) == installChannelNightly {
408			return "curl -fsSL https://entire.io/install.sh | bash -s -- --channel nightly"
409		}
410		return "curl -fsSL https://entire.io/install.sh | bash"
411	}
412	
413	func UpdateCommandForCurrentBinary(currentVersion string) string {
414		if !canAutoInstall() {
415			return downloadsURL
416		}
417		return updateCommand(currentVersion)
418	}
419	
420	// printNotification prints the version update notification to the user.
421	func printNotification(w io.Writer, current, latest string) {
422		fmt.Fprintf(w, "\nUpdate available! %s -> %s\nRelease notes: %s\n",
423			displayVersion(current), displayVersion(latest), releaseNotesURL(latest))
424	}
